function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 3 || arr.length > 1000) return 'arr needs 3 to 1000 values.';
  for (let i = 0; i < arr.length; i++) {
    if (!Number.isInteger(arr[i]) || arr[i] < 1 || arr[i] > 1000000000) return 'Each value is an integer from 1 to 10^9.';
    if (i > 0 && arr[i - 1] >= arr[i]) return 'arr must be strictly increasing.';
  }
  return null;
}

