function lenLongestFibSubseq(arr) {
  const n = arr.length;
  const index = new Map();
  for (let i = 0; i < n; i++) {
    index.set(arr[i], i);
  }
  const dp = Array.from({ length: n }, () => new Array(n).fill(2));
  let best = 0;

  for (let k = 2; k < n; k++) {
    for (let j = k - 1; j > 0 && arr[k] - arr[j] < arr[j]; j--) {
      const i = index.get(arr[k] - arr[j]);
      if (i !== undefined) {
        dp[j][k] = dp[i][j] + 1;
        best = Math.max(best, dp[j][k]);
      }
    }
  }
  return best;
}

