function lenLongestFibSubseq(arr) {
  // Every pair of first two terms fixes the rest of the sequence; extend each pair as far as the set allows.
  const present = new Set(arr);
  let answer = 0;
  for (let a = 0; a < arr.length; a++) {
    for (let b = a + 1; b < arr.length; b++) {
      let x = arr[a];
      let y = arr[b];
      let length = 2;
      while (present.has(x + y)) {
        const z = x + y;
        x = y;
        y = z;
        length++;
      }
      if (length >= 3) answer = Math.max(answer, length);
    }
  }
  return answer;
}

