function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const limit = large ? 1000000000 : pick(10, 60);
  const target = large ? 1000 : pick(3, 12);
  const values = new Set();
  // Plant a few Fibonacci-like chains, then fill up with random values.
  const chains = large ? pick(1, 4) : pick(0, 2);
  for (let c = 0; c < chains && values.size < target; c++) {
    let a = pick(1, large ? 1000 : 5);
    let b = a + pick(1, large ? 5000 : 6);
    if (rand() < 0.3) [a, b] = [b, a];
    const keepEach = rand() < 0.5 ? 1 : 0.8;
    while (a <= limit && values.size < target) {
      if (rand() < keepEach) values.add(a);
      [a, b] = [b, a + b];
    }
  }
  while (values.size < target) values.add(pick(1, limit));
  return [[...values].sort((x, y) => x - y)];
}
